import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import ClientError


def _to_millis(dt: datetime) -> int:
    return int(dt.timestamp() * 1000)


def _parse_time_range(
    start_time: Optional[str] = None,
    end_time: Optional[str] = None,
    recent_minutes: int = 60,
) -> tuple[datetime, datetime]:
    now = datetime.now(timezone.utc)
    if end_time:
        end_dt = datetime.fromisoformat(end_time.replace("Z", "+00:00"))
    else:
        end_dt = now
    if start_time:
        start_dt = datetime.fromisoformat(start_time.replace("Z", "+00:00"))
    else:
        start_dt = end_dt - timedelta(minutes=recent_minutes)
    return start_dt.astimezone(timezone.utc), end_dt.astimezone(timezone.utc)


def _build_filter_pattern(field_filters: Dict[str, str]) -> str:
    parts = []
    for key, value in field_filters.items():
        if value is None:
            continue
        escaped = str(value).replace('"', r'\"')
        parts.append(f'{{ $.{key} = "{escaped}" }}')
    return " && ".join(parts) if parts else ""


def query_recent_logs(
    log_group_name: str,
    field_filters: Optional[Dict[str, str]] = None,
    start_time: Optional[str] = None,
    end_time: Optional[str] = None,
    recent_minutes: int = 60,
    limit: int = 100,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Query recent Amazon CloudWatch Logs entries filtered by field values and time range.

    Environment variables:
      AWS_ACCESS_KEY_ID
      AWS_SECRET_ACCESS_KEY
      AWS_REGION
    """
    field_filters = field_filters or {}
    start_dt, end_dt = _parse_time_range(start_time=start_time, end_time=end_time, recent_minutes=recent_minutes)

    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    client = boto3.client("logs", region_name=region)

    kwargs: Dict[str, Any] = {
        "logGroupName": log_group_name,
        "startTime": _to_millis(start_dt),
        "endTime": _to_millis(end_dt),
        "limit": limit,
        "interleaved": True,
    }

    filter_pattern = _build_filter_pattern(field_filters)
    if filter_pattern:
        kwargs["filterPattern"] = filter_pattern

    results: List[Dict[str, Any]] = []
    next_token: Optional[str] = None

    try:
        while True:
            if next_token:
                kwargs["nextToken"] = next_token
            response = client.filter_log_events(**kwargs)
            for event in response.get("events", []):
                results.append(
                    {
                        "logStreamName": event.get("logStreamName"),
                        "timestamp": event.get("timestamp"),
                        "ingestionTime": event.get("ingestionTime"),
                        "message": event.get("message"),
                        "eventId": event.get("eventId"),
                    }
                )
                if len(results) >= limit:
                    return results[:limit]

            prev_token = next_token
            next_token = response.get("nextToken")
            if not next_token or next_token == prev_token:
                break
    except ClientError as e:
        raise RuntimeError(f"CloudWatch Logs query failed: {e}") from e

    return results


if __name__ == "__main__":
    import json
    import sys

    if len(sys.argv) < 2:
        raise SystemExit(
            "Usage: python script.py <log_group_name> [key=value ...] "
            "[--start ISO8601] [--end ISO8601] [--minutes N] [--limit N]"
        )

    log_group = sys.argv[1]
    filters: Dict[str, str] = {}
    start = None
    end = None
    minutes = 60
    limit = 100

    args = sys.argv[2:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--start" and i + 1 < len(args):
            start = args[i + 1]
            i += 2
        elif arg == "--end" and i + 1 < len(args):
            end = args[i + 1]
            i += 2
        elif arg == "--minutes" and i + 1 < len(args):
            minutes = int(args[i + 1])
            i += 2
        elif arg == "--limit" and i + 1 < len(args):
            limit = int(args[i + 1])
            i += 2
        elif "=" in arg:
            k, v = arg.split("=", 1)
            filters[k] = v
            i += 1
        else:
            i += 1

    print(
        json.dumps(
            query_recent_logs(
                log_group_name=log_group,
                field_filters=filters,
                start_time=start,
                end_time=end,
                recent_minutes=minutes,
                limit=limit,
            ),
            default=str,
            indent=2,
        )
    )
